# Builds esp32/include/certs.h from the PEM files generated by certgen (under pki/).
# Usage (from repo root): powershell -File src\esp32\tools\gen_certs_header.ps1
# Or pass explicit paths under src\pki with -Ca, -Cert, and -Key.
param(
  [string]$Pki = (Join-Path $PSScriptRoot "..\..\pki"),
  [string]$Ca, [string]$Cert, [string]$Key
)
$ErrorActionPreference = "Stop"
if (-not (Test-Path $Pki)) { throw "pki folder not found: $Pki (run certgen first)" }
$files = Get-ChildItem $Pki -Recurse -File

function Pick($label, $current, $filter) {
  if ($current) { return (Resolve-Path $current).Path }
  $m = $files | Where-Object $filter | Select-Object -First 1
  if (-not $m) {
    Write-Host "Could not auto-find $label. Files in pki/:"; $files | ForEach-Object { Write-Host "  $($_.FullName)" }
    throw "Pass -Ca / -Cert / -Key explicitly."
  }
  return $m.FullName
}
$Ca   = Pick "CA certificate"     $Ca   { $_.Name -match '^(rootCA|ca)\.(crt|pem)$' }
$Cert = Pick "client certificate" $Cert { $_.Name -match 'client.*\.(crt|pem)$' }
$Key  = Pick "client private key" $Key  { $_.Name -match 'client.*\.key$' }

if ((Split-Path $Key -Leaf) -match 'rootCA|^ca\.') { throw "Refusing to embed a CA private key." }
$keyText = (Get-Content $Key -Raw)
if ($keyText -notmatch 'PRIVATE KEY') { throw "$Key is not a PEM private key." }

function Lit($name, $path) {
  $t = (Get-Content $path -Raw).Trim()
  return "static const char $name[] = R`"PEM($t)PEM`";`n"
}
$out = "// AUTO-GENERATED - contains a private key. Ignored by Git. Do not share.`n#pragma once`n`n"
$out += Lit "CA_CERT" $Ca
$out += Lit "CLIENT_CERT" $Cert
$out += Lit "CLIENT_KEY" $Key

$dest = Join-Path $PSScriptRoot "..\include\certs.h"
Set-Content -Path $dest -Value $out -Encoding ASCII
Write-Host "Wrote $dest"
Write-Host "CA:   $Ca`nCert: $Cert`nKey:  $Key"
